inline const ItemData* GetByShortname(const char* shortname) noexcept
{
    if (!shortname) return nullptr;
    for (std::size_t i = 0; i < kCount; ++i)
        if (std::strcmp(kData[i].shortname, shortname) == 0) return &kData[i];
    return nullptr;
}

inline std::int32_t GetItemId(const char* shortname) noexcept
{
    const ItemData* item = GetByShortname(shortname);
    return item ? item->item_id : 0;
}

inline const char* GetShortname(std::int32_t itemId) noexcept
{
    const ItemData* item = GetByItemId(itemId);
    return item ? item->shortname : nullptr;
}

inline const char* const* GetModTypes(const ItemData* item, std::size_t& count) noexcept
{
    if (!item) { count = 0; return nullptr; }
    count = item->mod_type_count;
    return count ? &kModTypes[item->first_mod_type] : nullptr;
}

inline const char* const* GetChildren(const ItemData* item, std::size_t& count) noexcept
{
    if (!item) { count = 0; return nullptr; }
    count = item->child_count;
    return count ? &kChildren[item->first_child] : nullptr;
}
